namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
    public int RatingCount => Ratings.Count;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class SubmitRecipeModel
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be under 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "A short description is required.")]
    [StringLength(300, ErrorMessage = "Description must be under 300 characters.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please list the ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please describe the steps.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public static readonly List<RecipeCategory> Categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day right with morning favorites" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you going" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and indulgent finishes" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Icon = "🥤", Description = "Refreshing beverages and cocktails" },
    ];

    public RecipeService()
    {
        _recipes = CreateSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() => Categories;

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetRecipe(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int rating)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && rating is >= 1 and <= 5)
            {
                recipe.Ratings.Add(rating);
            }
        }
    }

    public Recipe AddRecipe(SubmitRecipeModel model)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = model.Title,
                Category = model.Category,
                Description = model.Description,
                Ingredients = model.Ingredients
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList(),
                Steps = model.Steps
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList(),
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy buttermilk pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups flour", "2 tbsp sugar", "1 tbsp baking powder", "1/2 tsp salt", "2 eggs", "1 1/2 cups buttermilk", "1/4 cup melted butter"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, buttermilk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Pour 1/4 cup batter onto a hot greased griddle.", "Cook until bubbles form, then flip and cook until golden."],
            Ratings = [5, 4, 5, 4, 5],
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, healthy, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice"],
            Steps = ["Toast the bread until golden and crispy.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread mashed avocado on toast.", "Top with red pepper flakes and serve."],
            Ratings = [4, 5, 4],
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp, creamy classic that never goes out of style.",
            Ingredients = ["1 head romaine lettuce", "1/2 cup Caesar dressing", "1/4 cup parmesan cheese", "1 cup croutons", "2 grilled chicken breasts"],
            Steps = ["Chop romaine lettuce and place in a large bowl.", "Slice grilled chicken into strips.", "Toss lettuce with Caesar dressing.", "Top with croutons, parmesan, and chicken."],
            Ratings = [4, 4, 5, 3],
        },
        new()
        {
            Id = 4, Title = "Grilled Cheese Sandwich", Category = "Lunch",
            Description = "Melty, buttery comfort food at its finest.",
            Ingredients = ["2 slices white bread", "2 slices cheddar cheese", "1 tbsp butter"],
            Steps = ["Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Cook in a skillet on medium heat until golden on each side."],
            Ratings = [5, 5, 4, 5],
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich, slow-simmered meat sauce over tender pasta.",
            Ingredients = ["1 lb spaghetti", "1 lb ground beef", "1 onion, diced", "3 cloves garlic", "1 can crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef with onion and garlic.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
            Ratings = [5, 5, 5, 4, 5],
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner",
            Description = "A quick weeknight dinner loaded with veggies.",
            Ingredients = ["2 chicken breasts, sliced", "1 bell pepper", "1 cup broccoli", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 clove garlic", "Cooked rice"],
            Steps = ["Heat sesame oil in a wok over high heat.", "Cook chicken until golden, then set aside.", "Stir-fry vegetables with garlic for 3 minutes.", "Return chicken to wok, add soy sauce, and toss.", "Serve over steamed rice."],
            Ratings = [4, 5, 4],
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Chewy, gooey cookies with pools of melted chocolate.",
            Ingredients = ["2 1/4 cups flour", "1 cup butter, softened", "3/4 cup sugar", "3/4 cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
            Steps = ["Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto a baking sheet.", "Bake at 375°F for 9-11 minutes."],
            Ratings = [5, 5, 5, 5, 4],
        },
        new()
        {
            Id = 8, Title = "Trail Mix", Category = "Snacks",
            Description = "A customizable mix of nuts, seeds, and dried fruit.",
            Ingredients = ["1 cup almonds", "1 cup cashews", "1/2 cup dried cranberries", "1/2 cup raisins", "1/2 cup chocolate chips", "1/4 cup sunflower seeds"],
            Steps = ["Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container."],
            Ratings = [4, 3, 4],
        },
        new()
        {
            Id = 9, Title = "Iced Lemonade", Category = "Drinks",
            Description = "Tart, sweet, and perfectly refreshing on a hot day.",
            Ingredients = ["1 cup fresh lemon juice", "1 cup sugar", "6 cups cold water", "Ice", "Lemon slices for garnish"],
            Steps = ["Dissolve sugar in 1 cup warm water to make simple syrup.", "Combine simple syrup, lemon juice, and remaining water.", "Stir well and serve over ice.", "Garnish with lemon slices."],
            Ratings = [5, 4, 5],
        },
    ];
}

