@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

@{
    var recipes = RecipeService.GetRecipesByCategory(CategoryName ?? "");
    var category = RecipeService.GetCategories()
        .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
}

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@(category?.Icon) @CategoryName Recipes</h1>
<p class="text-muted">@(category?.Description)</p>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes in this category yet. <a href="/submit">Be the first to add one!</a></div>
}
else
{
    <div class="row g-3">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="/recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                        </h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <span class="text-muted ms-1">(@recipe.RatingCount)</span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{RecipeId:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService RecipeService

@{
    var recipe = RecipeService.GetRecipe(RecipeId);
}

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Steps</h4>
            <ol class="list-group list-group-numbered mb-3">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h5 class="card-title">Rate This Recipe</h5>
            <StarRating RecipeId="RecipeId" @rendermode="InteractiveServer" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }
}

@page "/submit"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@rendermode InteractiveServer

@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added.
        <a href="/recipe/@_submittedRecipeId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Name">@cat.Icon @cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => _model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2"
            placeholder="A brief description of your dish" />
        <ValidationMessage For="() => _model.Description" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.Ingredients" rows="5"
            placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" @bind-Value="_model.Steps" rows="5"
            placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        <ValidationMessage For="() => _model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private SubmitRecipeModel _model = new();
    private bool _submitted;
    private int _submittedRecipeId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(_model);
        _submittedRecipeId = recipe.Id;
        _submitted = true;
        _model = new SubmitRecipeModel();
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div>
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_hovered > 0 ? _hovered : _selected) ? "filled" : "")"
                  role="button"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0">
                @(star <= (_hovered > 0 ? _hovered : _selected) ? "★" : "☆")
            </span>
        }
    </span>

    @if (_selected > 0)
    {
        <span class="ms-2 text-success">You rated this @_selected/5!</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click a star to rate</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _selected;
    private int _hovered;

    private void SubmitRating(int rating)
    {
        _selected = rating;
        RecipeService.AddRating(RecipeId, rating);
    }
}

